const FOOT=()=>`<footer><details><summary>${L("Real NASA data vs pretend","بيانات ناسا الحقيقية والخيالية")}</summary>${L("REAL: archived NASA DONKI solar flare dates, the 2018 Mars dust storm (Opportunity), Curiosity RAD radiation, MOXIE, InSight marsquakes, Phoenix water ice. Game events use archived data; the “LIVE” line on the home screen comes from NASA’s DONKI API when available. Pretend: leaks, strange rocks, and all meter numbers. Not affiliated with or endorsed by NASA; uses NASA public data.","حقيقي: تواريخ توهجات شمسية مؤرشفة من ناسا (DONKI)، عاصفة غبار المريخ 2018 (أوبورتيونيتي)، إشعاع كيوريوسيتي، موكسي، زلازل إنسايت، وجليد فينيكس. أحداث اللعبة من بيانات مؤرشفة، أما سطر «مباشر» في الصفحة الرئيسية فمن واجهة ناسا DONKI عند توفرها. الخيالي: التسرب والصخور الغريبة وكل أرقام العدادات. اللعبة غير تابعة لناسا ولا معتمدة منها، وتستخدم بيانات ناسا العامة.")}</details></footer>`;
const BEEP=t=>`<div class="card beep">${sv_("bot","rb bob")}<div class="bub" id="bub">${I(t)}</div></div>`;
