const NKEY="bBcp8mW69wpCBfjh6bPpFfFWRCJHtKq7Mmcggmtn"; // swap for your own free key from https://api.nasa.gov (higher rate limits)
const NA={neo:null,apod:null,mars:null,wx:null,mi:0,ready:false,started:false};
const esc=s=>String(s==null?"":s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const safeU=u=>/^https?:\/\//.test(u||"")?String(u).replace(/^http:/,"https:"):"";
const ymd=d=>d.toISOString().slice(0,10);
// cached in localStorage so we stay inside the shared DEMO_KEY rate limit
async function nf(key,url,ttl,tf){
 let c=null;try{c=JSON.parse(localStorage.getItem("ozc:"+key))}catch(e){}
 if(c&&c.d&&Date.now()-c.t<ttl)return c.d;
 try{const r=await fetch(url);if(!r.ok)throw 0;let d=await r.json();if(tf)d=tf(d);if(d==null)throw 0;
  try{localStorage.setItem("ozc:"+key,JSON.stringify({t:Date.now(),d}))}catch(e){}return d}
 catch(e){return c&&c.d?c.d:null}}
const fr=c=>"ABCMX".indexOf((c||"A")[0])*1000+(parseFloat((c||"").slice(1))||0);
const sev=c=>{const l=(c||"")[0],n=parseFloat((c||"").slice(1))||0;return l=="X"?(n>=10?4:3):l=="M"?2:1};
async function loadWX(){
 if(NA.wx)return;
 const e=new Date(),b=new Date(e-30*864e5),q=`startDate=${ymd(b)}&endDate=${ymd(e)}&api_key=${NKEY}`;
 const[f,c]=await Promise.all([
  nf("flr",`https://api.nasa.gov/DONKI/FLR?${q}`,108e5,a=>Array.isArray(a)?a.filter(x=>x.classType).map(x=>({c:x.classType,t:x.peakTime||x.beginTime||""})):null),
  nf("cme",`https://api.nasa.gov/DONKI/CME?${q}`,108e5,a=>Array.isArray(a)?a.length:null)]);
 if(!f||!f.length)return;
 const s=[...f].sort((a,b)=>a.t<b.t?-1:1),last=s[s.length-1],mx=f.reduce((a,b)=>fr(b.c)>fr(a.c)?b:a);
 NA.wx={n:f.length,cme:c,max:mx.c,md:mx.t.slice(0,10)};
 LIVE={c:last.c,d:last.t.slice(0,10)};mc();
 // the strongest real flare of the last 30 days becomes a possible storm in the game
 if(!FL.some(x=>x.live)){const d=NA.wx.md;FL.push({live:1,n:["Fresh Solar Flare","توهج شمسي جديد"],d:[d,d],x:["class "+mx.c+" flare spotted by NASA this month","توهج من الفئة "+mx.c+" رصدته ناسا هذا الشهر"],v:sev(mx.c)})}
 if(V=="home")draw()}
const loadNEO=async()=>{const d=ymd(new Date());NA.neo=await nf("neo",`https://api.nasa.gov/neo/rest/v1/feed?start_date=${d}&end_date=${d}&api_key=${NKEY}`,108e5,r=>{const a=r&&r.near_earth_objects&&Object.values(r.near_earth_objects).flat();if(!a||!a.length)return null;const k=x=>+((x.close_approach_data[0]||{}).miss_distance||{}).kilometers||1e12,c=a.reduce((p,q)=>k(q)<k(p)?q:p);return{n:a.length,nm:String(c.name).replace(/[()]/g,""),km:Math.round(k(c)),m:Math.round(c.estimated_diameter.meters.estimated_diameter_max)}})};
const loadAP=async()=>{NA.apod=await nf("apod",`https://api.nasa.gov/planetary/apod?api_key=${NKEY}`,216e5,d=>d&&d.title?{t:d.title,u:d.url,m:d.media_type,e:d.explanation||"",d:d.date,c:d.copyright||""}:null)};
const loadMars=async()=>{NA.mars=await nf("mars",`https://api.nasa.gov/mars-photos/api/v1/rovers/perseverance/latest_photos?api_key=${NKEY}`,216e5,d=>{const p=d&&d.latest_photos;return p&&p.length?p.slice(0,8).map(x=>({u:x.img_src,s:x.sol,e:x.earth_date,c:(x.camera&&x.camera.full_name)||""})):null})};
function loadNASA(){
 if(NA.started&&(!NA.ready||(NA.apod&&NA.mars&&NA.wx)))return;
 NA.started=true;NA.ready=false;
 Promise.all([loadWX(),loadAP(),loadMars(),loadNEO()]).catch(()=>{}).then(()=>{NA.ready=true;if(V=="nasa")draw()})}
