// ----- Mission Control quiz (after each night) -----
const QZ=[
{q:["What gas is most of Mars’s air made of?","ما الغاز الذي يشكل معظم هواء المريخ؟"],o:[["Oxygen","الأكسجين"],["Carbon dioxide","ثاني أكسيد الكربون"],["Helium","الهيليوم"]],a:1,e:["About 95% of it! That’s why MOXIE can turn it into oxygen.","نحو 95% منه! ولهذا يستطيع موكسي تحويله إلى أكسجين."]},
{q:["How long is one Mars day (a sol)?","كم يدوم يوم المريخ (السول)؟"],o:[["About 24 h 39 min","نحو 24 ساعة و39 دقيقة"],["About 12 hours","نحو 12 ساعة"],["About 48 hours","نحو 48 ساعة"]],a:0,e:["Just a little longer than an Earth day.","أطول قليلاً فقط من يوم الأرض."]},
{q:["Which rover carries MOXIE, the oxygen-making machine?","أي مركبة جوالة تحمل موكسي، جهاز صنع الأكسجين؟"],o:[["Opportunity","أوبورتيونيتي"],["Sojourner","سوجورنر"],["Perseverance","بيرسيفرنس"]],a:2,e:["MOXIE made breathable oxygen from Mars air.","صنع موكسي أكسجيناً صالحاً للتنفس من هواء المريخ."]},
{q:["How long does a message take to travel between Earth and Mars?","كم تستغرق رسالة بين الأرض والمريخ؟"],o:[["No time at all","لا وقت إطلاقاً"],["4 to 24 minutes","من 4 إلى 24 دقيقة"],["4 to 24 hours","من 4 إلى 24 ساعة"]],a:1,e:["It depends on where the planets are in their orbits.","يعتمد ذلك على موقع الكوكبين في مداريهما."]},
{q:["What protects Earth from most solar particles?","ما الذي يحمي الأرض من معظم الجسيمات الشمسية؟"],o:[["Its air and magnetic field","هواؤها ومجالها المغناطيسي"],["The Moon","القمر"],["Its oceans","محيطاتها"]],a:0,e:["Mars has almost none, so crews need a shield!","المريخ يكاد يخلو منهما، لذا يحتاج الطاقم إلى درع!"]},
{q:["What was Jezero Crater, where Perseverance explores, long ago?","ماذا كانت فوهة جيزيرو، حيث تستكشف بيرسيفرنس، قبل زمن بعيد؟"],o:[["A volcano","بركاناً"],["A lake","بحيرة"],["A forest","غابة"]],a:1,e:["Water once flowed there, a great place to look for signs of life.","جرى الماء هناك يوماً، وهو مكان رائع للبحث عن علامات الحياة."]},
{q:["Why do astronauts on the ISS exercise about two hours every day?","لماذا يمارس رواد المحطة الفضائية الرياضة نحو ساعتين يومياً؟"],o:[["Just for fun","للمتعة فقط"],["To keep bones and muscles strong","للحفاظ على قوة العظام والعضلات"],["To make more oxygen","لصنع مزيد من الأكسجين"]],a:1,e:["Without gravity pulling on them, bones and muscles weaken. NASA’s OSDR stores studies on this.","بدون جاذبية تشدّها تضعف العظام والعضلات. ويحتفظ مستودع ناسا OSDR بدراسات عن ذلك."]},
{q:["What is Ingenuity?","ما هي إنجينيويتي؟"],o:[["A space telescope","تلسكوب فضائي"],["A moon rocket","صاروخ قمري"],["A Mars helicopter","مروحية على المريخ"]],a:2,e:["It flew 72 times on Mars!","حلّقت 72 مرة على المريخ!"]},
{q:["Dust on solar panels is a problem because it…","الغبار على الألواح الشمسية مشكلة لأنه…"],o:[["blocks sunlight, so less power","يحجب الضوء فتقل الطاقة"],["makes panels too hot","يجعل الألواح ساخنة جداً"],["makes oxygen","يصنع الأكسجين"]],a:0,e:["That’s why the Solar Farm needs brushing!","ولهذا تحتاج المزرعة الشمسية إلى المسح!"]},
{q:["A solar flare is…","التوهج الشمسي هو…"],o:[["a Mars sandstorm","عاصفة رملية على المريخ"],["a rocket launch","إطلاق صاروخ"],["a burst of light and particles from the Sun","انفجار من الضوء والجسيمات من الشمس"]],a:2,e:["NASA’s DONKI keeps a record of them.","تحتفظ DONKI التابعة لناسا بسجل لها."]}];
function quiz(){const q=QZ[(S.qz+S.sol)%QZ.length],a=S.qa;
 return`<div class="sci quiz"><b>${L("Quick quiz: get it right for +1 ","اختبار سريع: أجب صح لتربح +1 ")}${sv_("pw")}</b><p style="margin:.4em 0">${LA(q.q)}</p>${q.o.map((x,i)=>`<button class="qb ${a==null?"":i==q.a?"good":i==a?"bad":""}" ${a==null?"":"disabled"} onclick="qa(${i})">${LA(x)}</button>`).join("")}${a!=null?`<p style="margin:.5em 0 0"><b>${a==q.a?L("Correct! +1 power for tomorrow.","صحيح! +1 طاقة لصباح الغد."):L("Not quite.","ليست صحيحة تماماً.")}</b> ${LA(q.e)}</p>`:""}</div>`}
function qa(i){if(!S||S.qa!=null)return;const q=QZ[(S.qz+S.sol)%QZ.length];S.qa=i;if(i==q.a){S.p=Math.min(10,S.p+1);S.qs=(S.qs||0)+1;try{SFX.gh()}catch(e){}}sv();nightModal();const c=document.querySelector(".mod .card");if(c)c.scrollTop=c.scrollHeight}
const RK=s=>s>=1500?L("Legend","أسطورة"):s>=1000?L("Commander","قائد"):s>=500?L("Pilot","طيار"):L("Cadet","متدرب");
const confetti=()=>`<div class="cf" aria-hidden="true">${Array.from({length:30},(_,i)=>`<i style="left:${(i*37+11)%100}%;background:${["#ff865d","#ffd86f","#72d9f2","#9be3ad","#c9b6f2"][i%5]};animation-delay:${(i%9)*.12}s;animation-duration:${2.4+(i%5)*.3}s"></i>`).join("")}</div>`;

document.documentElement.lang=LG;document.documentElement.dir=LG=="ar"?"rtl":"ltr";draw();
loadWX();if(!P.seen)tut();
